PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?zone ?label ?cls WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?label }
  OPTIONAL { ?zone brick:hasPoint ?pt . ?pt a ?cls }
} LIMIT 100

SELECT ?zuri ?pturi ?c WHERE {
  ?z a brick:HVAC_Zone ; brick:hasPoint ?p .
  BIND(IF(?z = ?zuri, ?z, ?z) AS ?ignored)
} LIMIT 5

