import csv
TS = '2018-04-09 16:00:00'
rows = list(csv.DictReader(open(CATALOG_CSV)))
zones = {}
for r in rows:
    local = r['point_uri'].split('#')[-1]
    zn, cls = local.rsplit('.',1)
    zones.setdefault(zn, {})[cls] = r['timeseries_id']

targets = {z:d for z,d in zones.items() if 'Zone_Air_Temperature_Sensor' in d and 'Zone_Air_Cooling_Temperature_Setpoint' in d}

# Load values
vals = {}
for r in csv.DictReader(open(VALUES_CSV)):
    vals.setdefault(r['timeseries_id'], {})[r['timestamp']] = r['value']

results = {}
for z, d in targets.items():
    ts_id = d['Zone_Air_Temperature_Sensor']
    cp_id = d['Zone_Air_Cooling_Temperature_Setpoint']
    t = vals.get(ts_id, {}).get(TS)
    c = vals.get(cp_id, {}).get(TS)
    if t is not None and c is not None:
        results[z] = float(t)-float(c)
    else:
        results[z] = None

for z,v in sorted(results.items(), key=lambda x: -(x[1] or -1e9)):
    print(z, v)

best = max((z for z in targets if results.get(z) is not None), key=lambda z: results[z])
print("BEST", best, results[best])

